import cookieParser from "cookie-parser";
import types from "./constants/types.js";
import Session from "./services/session.js";

const session = ({
  secret,
  expiry = 24 * 60 * 60,
  client,
  type = types.STANDARD,
  breakOnInValidate = false,
  validateToNext = false,
  onInvalidate = () => {},
}) => {
  const ses = new Session(client, secret, expiry, type);

  const whenInvalidate = async (errMessage) => {
    await onInvalidate();
    if (breakOnInValidate) throw new Error(errMessage);
    return false;
  };

  const setSession = async (req, res, value) => {
    const sessionToken = await ses.initialize(value);
    res.cookie("sessionToken", sessionToken, { httpOnly: true });
    return sessionToken;
  };

  const validate = async (req, res = false, next = false) => {
    await new Promise((resolve) => cookieParser()(req, res, resolve));
    const token = req.cookies["sessionToken"];
    req.session = token;
    if ([null, undefined].includes(token))
      return await whenInvalidate("No session");

    const result = await ses.validate(token);
    if (!result.valid) return await whenInvalidate("Session expired");

    if (validateToNext) {
      req.sessionValue = result.value;
      next();
    } else return result.value;
  };

  return { setSession, validate };
};

export const sessionTypes = types;

export default session;
